import { getFirebaseAuth } from '@/lib/firebase/client'
import { deleteContentDocument } from '@/lib/firebase/content-services'
import type { MediaDocument } from '@/types/firestore'

/*
 * Penghapusan permanen satu media: berkas ImageKit lebih dulu, dokumen
 * pustakanya menyusul.
 *
 * Urutannya penting dan bukan selera. Kalau dokumen Firestore yang dihapus
 * lebih dulu lalu ImageKit gagal, yang tersisa adalah berkas yatim di ImageKit
 * yang tidak muncul di panel mana pun: tidak ada yang tahu ia ada, tidak ada
 * yang bisa mengulang penghapusannya, dan kuota akun tetap terpakai. Dengan
 * urutan ini, kegagalan di tengah meninggalkan dokumen pustaka yang masih
 * terlihat, dan menekan tombolnya sekali lagi menyelesaikan sisanya.
 */

export type MediaDeletionResult = {
  /** Berkasnya benar-benar dihapus pada percobaan ini. */
  binaryRemoved: boolean
  /** Berkasnya sudah tidak ada di ImageKit sebelum percobaan ini. */
  binaryMissing: boolean
}

async function currentIdToken() {
  const user = getFirebaseAuth().currentUser

  if (!user) {
    throw new Error('Sesi admin sudah berakhir. Masuk ulang lalu coba lagi.')
  }

  return user.getIdToken()
}

export async function deleteImageKitFile(fileId: string): Promise<{ missing: boolean }> {
  const response = await fetch(`/api/admin/media?fileId=${encodeURIComponent(fileId)}`, {
    method: 'DELETE',
    headers: { authorization: `Bearer ${await currentIdToken()}` },
  })
  const body = (await response.json().catch(() => null)) as
    | { error?: string; missing?: boolean }
    | null

  if (!response.ok) {
    throw new Error(body?.error || 'Berkas gagal dihapus dari ImageKit.')
  }

  return { missing: Boolean(body?.missing) }
}

export async function deleteMediaPermanently(media: MediaDocument): Promise<MediaDeletionResult> {
  // Dokumen lama hasil impor bisa saja tidak punya `fileId`. Tidak ada berkas
  // yang bisa dituju, tetapi catatannya tetap harus bisa dibersihkan.
  const binary = media.fileId ? await deleteImageKitFile(media.fileId) : { missing: true }

  await deleteContentDocument('media', media.id)

  return { binaryRemoved: !binary.missing, binaryMissing: binary.missing }
}
