import { listContentDocuments } from '@/lib/firebase/content-services'
import type { FirestoreCollectionName, FirestoreDocument, MediaDocument } from '@/types/firestore'

/*
 * Mencari siapa saja yang masih memakai sebuah gambar sebelum ia dihapus.
 *
 * Menghapus media berarti menghapus berkasnya di ImageKit, dan berkas ImageKit
 * tidak bisa dikembalikan. Kalau berkas itu ternyata masih dipakai satu berita
 * lama, yang terjadi bukan pesan kesalahan melainkan kotak gambar rusak di
 * halaman publik yang tidak ada yang melihat sampai ada yang melapor.
 *
 * Pencocokannya sengaja lebar, karena tidak semua pemakaian tercatat sebagai
 * id. Slot dan editor halaman menyimpan `mediaId`, tetapi cover berita, foto
 * pengurus, dan gambar di dalam isi artikel hanya menyimpan URL-nya sebagai
 * teks biasa. Karena itu seluruh nilai teks dokumen ditelusuri, bukan hanya
 * field yang kita tahu namanya hari ini: field baru yang menyimpan URL gambar
 * akan ikut terdeteksi tanpa ada yang perlu ingat memperbarui daftar di sini.
 *
 * Salah tebak di sini hanya berakibat satu arah. Pemakaian palsu membuat
 * penghapusan tertahan dan pengurus harus memeriksa sendiri; pemakaian yang
 * terlewat membuat gambar hilang dari halaman yang masih membutuhkannya.
 */

export type MediaUsageReason = 'assignment' | 'url'

export type MediaUsage = {
  collection: FirestoreCollectionName
  collectionLabel: string
  documentId: string
  documentLabel: string
  reason: MediaUsageReason
}

export type MediaUsageSource = {
  collection: FirestoreCollectionName
  label: string
  documents: FirestoreDocument[]
}

/**
 * Collection yang isinya bisa menunjuk ke sebuah gambar.
 *
 * `media` sendiri tidak ada di sini: dokumen yang sedang dihapus bukan
 * pemakainya. `partners` dan `divisions` juga tidak, karena keduanya tidak
 * menyimpan gambar sama sekali; menambahkannya nanti cukup satu baris.
 */
export const mediaUsageSources = [
  { collection: 'mediaSlots', label: 'Slot situs' },
  { collection: 'pageContents', label: 'Halaman terbit' },
  { collection: 'pageContentDrafts', label: 'Draf halaman' },
  { collection: 'articles', label: 'Berita' },
  { collection: 'announcements', label: 'Pengumuman' },
  { collection: 'gallery', label: 'Galeri' },
  { collection: 'leaders', label: 'Pengurus' },
  { collection: 'programs', label: 'Program kerja' },
  { collection: 'settings', label: 'Pengaturan situs' },
] as const satisfies readonly { collection: FirestoreCollectionName; label: string }[]

export const mediaUsageReasonLabels: Record<MediaUsageReason, string> = {
  assignment: 'Dipilih lewat pustaka',
  url: 'URL gambar tertanam',
}

/**
 * Potongan teks yang menandakan sebuah nilai menunjuk ke berkas ini.
 *
 * `filePath` didahulukan karena ia bertahan pada semua bentuk URL ImageKit:
 * URL dengan transformasi (`/tr:w-800/hmte/berita/foo.webp`) tetap memuat
 * lintasan berkasnya utuh, sedangkan `url` yang tersimpan di dokumen belum
 * tentu sama persis dengan `url` yang tercatat di pustaka.
 */
export function buildMediaNeedles(media: Pick<MediaDocument, 'filePath' | 'url'>): string[] {
  const candidates = [media.filePath, media.url]
    .map((value) => (typeof value === 'string' ? value.trim() : ''))
    .filter((value) => value.length > 0)

  return [...new Set(candidates)]
}

function collectStrings(value: unknown, found: string[]) {
  if (typeof value === 'string') {
    found.push(value)
    return
  }

  if (Array.isArray(value)) {
    value.forEach((item) => collectStrings(item, found))
    return
  }

  // Timestamp Firestore ikut tersaring lewat cabang ini dan hanya menghasilkan
  // angka, jadi tidak perlu diperlakukan khusus.
  if (value && typeof value === 'object') {
    Object.values(value as Record<string, unknown>).forEach((item) => collectStrings(item, found))
  }
}

/** Alasan sebuah dokumen dianggap memakai media, atau null kalau tidak memakainya. */
export function findMediaReference(
  document: Record<string, unknown>,
  media: Pick<MediaDocument, 'id' | 'filePath' | 'url'>,
): MediaUsageReason | null {
  if (typeof document.mediaId === 'string' && document.mediaId === media.id) {
    return 'assignment'
  }

  const assignments = document.mediaAssignments
  if (assignments && typeof assignments === 'object' && !Array.isArray(assignments)) {
    if (Object.values(assignments as Record<string, unknown>).includes(media.id)) {
      return 'assignment'
    }
  }

  const needles = buildMediaNeedles(media)
  if (needles.length === 0) return null

  const values: string[] = []
  collectStrings(document, values)

  return values.some((value) => needles.some((needle) => value.includes(needle))) ? 'url' : null
}

/** Judul dokumen yang bisa dikenali pengurus, bukan id acak Firestore. */
export function describeUsageDocument(document: Record<string, unknown>): string {
  const labelKeys = ['title', 'name', 'label', 'slotKey', 'pageKey', 'siteName']

  for (const key of labelKeys) {
    const value = document[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }

  return typeof document.id === 'string' && document.id ? document.id : 'Dokumen tanpa judul'
}

export function findMediaUsages(
  media: Pick<MediaDocument, 'id' | 'filePath' | 'url'>,
  sources: MediaUsageSource[],
): MediaUsage[] {
  return sources.flatMap((source) =>
    source.documents.flatMap((document) => {
      const record = document as unknown as Record<string, unknown>
      const reason = findMediaReference(record, media)

      if (!reason) return []

      return [{
        collection: source.collection,
        collectionLabel: source.label,
        documentId: document.id,
        documentLabel: describeUsageDocument(record),
        reason,
      }]
    }),
  )
}

/**
 * Membaca seluruh collection pemakai lalu menyimpulkan pemakaian.
 *
 * Sengaja tidak menangkap error sendiri. Daftar pemakaian yang gagal dibaca
 * tidak sama dengan daftar pemakaian yang kosong, dan memperlakukannya sama
 * berarti menghapus berkas justru pada saat kita paling tidak tahu apa-apa.
 */
export async function loadMediaUsages(
  media: Pick<MediaDocument, 'id' | 'filePath' | 'url'>,
): Promise<MediaUsage[]> {
  const sources = await Promise.all(
    mediaUsageSources.map(async (source) => ({
      collection: source.collection,
      label: source.label,
      documents: await listContentDocuments<FirestoreDocument>(source.collection),
    })),
  )

  return findMediaUsages(media, sources)
}
